package com.example.leagueticket.controller;
import com.example.leagueticket.common.Result;import com.example.leagueticket.dto.MatchScoreRequest;import com.example.leagueticket.security.AuthenticatedUser;import com.example.leagueticket.service.MatchResultWorkflowService;import com.example.leagueticket.vo.MatchResultWorkflowResponse;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.context.annotation.Profile;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/admin/result-reviews") @Profile("dev") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class AdminMatchResultReviewController {private final MatchResultWorkflowService service;@GetMapping public Result<List<MatchResultWorkflowResponse>> pending(){return Result.success(service.pending());}@GetMapping("/{matchId}") public Result<MatchResultWorkflowResponse> detail(@PathVariable Long matchId){return Result.success(service.detail(matchId));}@PostMapping("/{matchId}/confirm") public Result<MatchResultWorkflowResponse> confirm(@PathVariable Long matchId,@AuthenticationPrincipal AuthenticatedUser user,@Valid @RequestBody MatchScoreRequest request){return Result.success(service.confirm(matchId,user.userId(),request));}}
